                    continue
                if grid[r + dr][left] != grid[r][c] or grid[r + dr][right] != grid[r][c]:
                    continue
                for x in range(left + 1, right):
                    if out[r + dr][x] == 0:
                        out[r + dr][x] = 2
    return out

