    """Fill the interior of monochrome V-shaped diagonal outlines with 2."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    out = [row[:] for row in grid]
    # For every pair of diagonals meeting at a vertex, fill between their arms.
    # Downward V: vertex at the top, arms extend down-left and down-right.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0:
                continue
            for d in range(1, min(h - r, c + 1, w - c)):
                rr = r + d
                if grid[rr][c-d] == color and grid[rr][c+d] == color:
                    for y in range(1, d):
                        if out[rr][c-d+y] == 0:
                            out[rr][c-d+y] = 2
                    for k in range(1, d):
                        if out[r+k][c] == 0:
                            out[r+k][c] = 2
    # Upward V: vertex at the bottom, arms extend up-left and up-right.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0:
                continue
            for d in range(1, min(r + 1, c + 1, w - c)):
                rr = r - d
                if grid[rr][c-d] == color and grid[rr][c+d] == color:
                    for y in range(1, d):
                        if out[rr][c-d+y] == 0:
                            out[rr][c-d+y] = 2
                    for k in range(1, d):
                        if out[r-k][c] == 0:
                            out[r-k][c] = 2
    return out

